1	package water
2	
3	import (
4		"bytes"
5		"errors"
6		"math"
7		"os"
8		"path/filepath"
9		"strings"
10		"testing"
11		"time"
12	)
13	
14	// 本文件的测试只针对一件事：录入只接受能作为合法 UTF-8 原样保存的文本。
15	// 样品编号、采样点编号或任一项目名含孤立 0xFF、0xFE 字节或不完整的多字节
16	// 序列时，整份提交必须返回空样品和可被 errors.Is(err, water.ErrInvalidText)
17	// 识别的专用文本编码错误：不留下部分记录（哪怕非法项目排在最后）、不占用
18	// 样品编号、不改变按点查看与最近有效结果，也不能被归为未知采样点、项目重复、
19	// 同编号冲突或走重复录入成功分支。真正的 U+FFFD（“�”）、中文、其它有效
20	// 多字节字符以及内部 U+0000 仍然接受；文本处理只去首尾空白。
21	
22	// notEncodingError 之外的这些错误都不允许冒充编码问题。
23	func assertEncodingError(t *testing.T, err error, label string) {
24		t.Helper()
25		if !errors.Is(err, ErrInvalidText) {
26			t.Fatalf("%s: 应返回 ErrInvalidText，实际为 %v", label, err)
27		}
28		for _, target := range []error{
29			ErrEmptyField, ErrUnknownPoint, ErrInvalidValue, ErrInvalidTime,
30			ErrNoMeasurements, ErrDuplicateItem, ErrSampleConflict,
31		} {
32			if errors.Is(err, target) {
33				t.Fatalf("%s: 编码问题不能被归为 %v: %v", label, target, err)
34			}
35		}
36	}
37	
38	func assertNoReplacementBytes(t *testing.T, dir, label string) {
39		t.Helper()
40		data, err := os.ReadFile(filepath.Join(dir, "water-data.json"))
41		if err != nil {
42			t.Fatalf("%s: 读取落盘文件: %v", label, err)
43		}
44		if bytes.Contains(data, []byte{0xEF, 0xBF, 0xBD}) {
45			t.Fatalf("%s: 被拒绝的非法文本被替换成 U+FFFD 落盘", label)
46		}
47	}
48	
49	// 非法文本出现在编号、采样点编号或任一项目名（含排在最后的项目）时整份拒绝，
50	// 不留下部分记录；即使提交同时还带着未知采样点、项目重复、非有限数值、
51	// 零采样时间等其它问题，也必须报告编码问题。
52	func TestSubmitSampleRejectsInvalidUTF8(t *testing.T) {
53		s, dir := open(t)
54		mustPoint(t, s, "P1", "取水口")
55		mustLimit(t, s, "P1", "pH", 8.0, at(1, 0))
56		mustLimit(t, s, "P1", "COD", 30.0, at(1, 0))
57	
58		bad := []string{
59			"S\xff",           // 孤立 0xFF
60			"S\xfe",           // 孤立 0xFE
61			"S\xe4\xb8",       // 不完整的三字节序列
62			"S\xc0\xaf",       // 非法多字节序列
63			"pH" + "\xff",     // 项目名末尾的孤立 0xFF
64			"浊度" + "\xfe",     // 合法中文后接孤立 0xFE
65			"\xe4\xb8" + "pH", // 项目名开头不完整序列
66		}
67	
68		submit := func(label, id, point string, at time.Time, ms ...Measurement) {
69			t.Helper()
70			got, err := s.SubmitSample(id, point, at, ms...)
71			assertEncodingError(t, err, label)
72			if got.ID != "" || got.PointID != "" || got.Status != "" || len(got.Measurements) != 0 {
73				t.Fatalf("%s: 失败必须返回空样品，实际为 %+v", label, got)
74			}
75		}
76	
77		// 编号非法
78		submit("编号含 0xFF", bad[0], "P1", at(10, 0), Measurement{Item: "pH", Value: 7})
79		submit("编号含 0xFE", bad[1], "P1", at(10, 0), Measurement{Item: "pH", Value: 7})
80		submit("编号含不完整序列", bad[2], "P1", at(10, 0), Measurement{Item: "pH", Value: 7})
81		// 采样点编号非法，即使该编号看起来未登记也不能报未知采样点
82		submit("采样点含 0xFF", "S-new-1", "P1"+"\xff", at(10, 0), Measurement{Item: "pH", Value: 7})
83		submit("编号与采样点都非法且采样点未登记", "S9"+"\xfe", "P9", at(10, 0), Measurement{Item: "pH", Value: 7})
84		// 项目名非法：排在最前、夹在中间、排在最后都要整份拒绝，不留部分记录
85		submit("首项非法", "S-new-2", "P1", at(10, 0),
86			Measurement{Item: bad[6], Value: 1}, Measurement{Item: "COD", Value: 20})
87		submit("中间项非法", "S-new-3", "P1", at(10, 0),
88			Measurement{Item: "pH", Value: 7}, Measurement{Item: bad[3], Value: 1}, Measurement{Item: "COD", Value: 20})
89		submit("末项非法且其余合法", "S-new-4", "P1", at(10, 0),
90			Measurement{Item: "pH", Value: 7}, Measurement{Item: "COD", Value: 20}, Measurement{Item: bad[4], Value: 1})
91		submit("末项为不完整序列", "S-new-5", "P1", at(10, 0),
92			Measurement{Item: "pH", Value: 7}, Measurement{Item: bad[5], Value: 1})
93	
94		// 编码问题优先于其它一切内容校验
95		submit("非法项目+项目重复", "S-new-6", "P1", at(10, 0),
96			Measurement{Item: "pH", Value: 1}, Measurement{Item: "pH", Value: 2}, Measurement{Item: bad[4], Value: 1})
97		submit("非法编号+零采样时间", bad[0], "P1", time.Time{}, Measurement{Item: "pH", Value: 7})
98		submit("非法项目+非有限数值", "S-new-7", "P1", at(10, 0),
99			Measurement{Item: "pH", Value: 7}, Measurement{Item: bad[4], Value: math.Inf(1)})
100	
101		// 全部拒绝之后：没有任何样品落盘或留在内存，编号没有被占用
102		if len(s.samples) != 0 {
103			t.Fatalf("被拒绝的提交不得留下记录，samples=%v", s.samples)
104		}
105		for _, id := range []string{"S-new-1", "S-new-2", "S-new-3", "S-new-4", "S-new-5", "S-new-6", "S-new-7"} {
106			if _, err := s.Confirm(id); !errors.Is(err, ErrUnknownSample) {
107				t.Fatalf("被拒绝编号 %s 不应能确认，got %v", id, err)
108			}
109		}
110		if list, err := s.ListByPoint("P1"); err != nil || len(list) != 0 {
111			t.Fatalf("按点查看不应出现被拒绝的记录: %+v err=%v", list, err)
112		}
113		if latest, ok, err := s.LatestResult("P1"); err != nil || ok || latest.ID != "" {
114			t.Fatalf("最近有效结果不应变化: %+v ok=%v err=%v", latest, ok, err)
115		}
116		assertNoReplacementBytes(t, dir, "全部拒绝后")
117	
118		// 先前失败占用过的编号改成合法文本后应能正常首次录入
119		saved := mustSample(t, s, "S-new-4", "P1", at(10, 0),
120			Measurement{Item: "pH", Value: 7}, Measurement{Item: "COD", Value: 25})
121		if saved.ID != "S-new-4" || saved.Status != StatusPending {
122			t.Fatalf("合法文本应能首次录入: %+v", saved)
123		}
124	}
125	
126	// 用已有已确认样品的编号提交非法文本：必须报编码错误，原测量值、状态、
127	// 逐项所用限值与生效时间、整份结论保持原样；不会走幂等成功或冲突分支。
128	func TestSubmitInvalidUTF8DoesNotTouchExistingSample(t *testing.T) {
129		s, dir := open(t)
130		mustPoint(t, s, "P1", "取水口")
131		mustLimit(t, s, "P1", "pH", 8.0, at(1, 0))
132		mustLimit(t, s, "P1", "COD", 30.0, at(1, 0))
133		mustSample(t, s, "S1", "P1", at(10, 0),
134			Measurement{Item: "pH", Value: 9}, Measurement{Item: "COD", Value: 30})
135		if _, err := s.Confirm("S1"); err != nil {
136			t.Fatalf("Confirm S1: %v", err)
137		}
138	
139		// 与已存内容完全一致、只是多带一个非法项目：不能幂等成功
140		got, err := s.SubmitSample("S1", "P1", at(10, 0),
141			Measurement{Item: "pH", Value: 9}, Measurement{Item: "COD", Value: 30},
142			Measurement{Item: "x\xff", Value: 1})
143		assertEncodingError(t, err, "已存编号+非法项目")
144		if got.ID != "" || got.Status != "" {
145			t.Fatalf("失败必须返回空样品，实际为 %+v", got)
146		}
147		// 非法采样点编号、非法项目名（即使内容本会冲突）也一样
148		_, err = s.SubmitSample("S1", "P1"+"\xfe", at(10, 0), Measurement{Item: "pH", Value: 9})
149		assertEncodingError(t, err, "已存编号+非法采样点")
150		_, err = s.SubmitSample("S1", "P1", at(10, 0),
151			Measurement{Item: "pH", Value: 9}, Measurement{Item: "COD", Value: 99})
152		// 对照：全合法但内容不同仍是既有冲突错误
153		if !errors.Is(err, ErrSampleConflict) {
154			t.Fatalf("对照应报同编号冲突，got %v", err)
155		}
156		_, err = s.SubmitSample("S1", "P1", at(10, 0),
157			Measurement{Item: "pH", Value: 9}, Measurement{Item: "COD\xff", Value: 99})
158		assertEncodingError(t, err, "已存编号+非法项目且值不同")
159	
160		// 原样品完整保持已确认状态与全部判定依据
161		checkTwoItemSaved(t, mustConfirm(t, s, "S1"), "非法提交后重复确认")
162		list, err := s.ListByPoint("P1")
163		if err != nil || len(list) != 1 {
164			t.Fatalf("按点查看数量变化: %+v err=%v", list, err)
165		}
166		checkTwoItemSaved(t, list[0], "非法提交后按点查看")
167		latest, ok, err := s.LatestResult("P1")
168		if err != nil || !ok {
169			t.Fatalf("最近有效结果变化: %+v ok=%v err=%v", latest, ok, err)
170		}
171		checkTwoItemSaved(t, latest, "非法提交后最近有效结果")
172	
173		// 重新打开后原样仍在，落盘文件中没有替换字符
174		if err := s.Close(); err != nil {
175			t.Fatalf("Close: %v", err)
176		}
177		assertNoReplacementBytes(t, dir, "重开前")
178		s2, err := Open(dir)
179		if err != nil {
180			t.Fatalf("reopen: %v", err)
181		}
182		defer s2.Close()
183		reopened, err := s2.ListByPoint("P1")
184		if err != nil || len(reopened) != 1 {
185			t.Fatalf("重开后记录变化: %+v err=%v", reopened, err)
186		}
187		checkTwoItemSaved(t, reopened[0], "重开后")
188	}
189	
190	func mustConfirm(t *testing.T, s *Store, id string) Sample {
191		t.Helper()
192		smp, err := s.Confirm(id)
193		if err != nil {
194			t.Fatalf("Confirm(%q): %v", id, err)
195		}
196		return smp
197	}
198	
199	// “�”（U+FFFD）本身是合法字符，中文、其它有效多字节字符和内部 U+0000
200	// 都照常接受；只去首尾空白，不做替换、大小写转换或额外归一化。成功录入后
201	// 编号、采样点归属和项目名在返回记录、按点查看与重开后的保存数据中保持一致。
202	func TestSubmitSampleAcceptsValidUnicodeText(t *testing.T) {
203		s, dir := open(t)
204		mustPoint(t, s, "P1", "一号取水口")
205	
206		// 含 U+FFFD、中文、emoji（四字节序列）、内部 U+0000 以及与 "pH" 仅大小写
207		// 不同的 "PH" 的项目名各自登记限值：若做大小写归一化，"pH"/"PH" 会撞成同一项。
208		items := []string{
209			"浊�度",     // 真正的替换字符 U+FFFD
210			"浊度",      // 中文
211			"溶氧🫧",     // 有效四字节字符
212			"ph\x00x", // 内部 U+0000 继续接受
213			"pH",
214			"PH",
215		}
216		for _, item := range items {
217			mustLimit(t, s, "P1", item, 100.0, at(1, 0))
218		}
219	
220		// 编号含 U+FFFD、首尾空白；项目名首尾空白只做去除
221		id := "  S-�-01  "
222		ms := []Measurement{
223			{Item: "  浊�度  ", Value: 1},
224			{Item: "浊度", Value: 2},
225			{Item: "溶氧🫧", Value: 3},
226			{Item: "ph\x00x", Value: 4},
227			{Item: "  pH  ", Value: 5},
228			{Item: "PH", Value: 6},
229		}
230		smp, err := s.SubmitSample(id, "  P1  ", at(10, 0), ms...)
231		if err != nil {
232			t.Fatalf("合法 Unicode 文本不应被拒绝: %v", err)
233		}
234		if smp.ID != "S-�-01" || smp.PointID != "P1" || len(smp.Measurements) != len(items) {
235			t.Fatalf("只应去掉首尾空白，实际为 %+v", smp)
236		}
237		gotItems := map[string]float64{}
238		for _, m := range smp.Measurements {
239			gotItems[m.Item] = m.Value
240		}
241		for _, m := range ms {
242			if gotItems[strings.TrimSpace(m.Item)] != m.Value {
243				t.Fatalf("项目名在返回记录中不一致: %+v", smp.Measurements)
244			}
245		}
246	
247		// 去首尾空白后相同仍是重复项目
248		if _, err := s.SubmitSample("S-dup", "P1", at(10, 0),
249			Measurement{Item: " pH ", Value: 1}, Measurement{Item: "pH", Value: 2}); !errors.Is(err, ErrDuplicateItem) {
250			t.Fatalf("去空白后相同的项目名仍属重复，got %v", err)
251		}
252	
253		// 含特殊字符的项目同样能按其名取到限值并完成确认
254		confirmed := mustConfirm(t, s, smp.ID)
255		if confirmed.Status != StatusConfirmed || len(confirmed.Results) != len(items) {
256			t.Fatalf("确认结果异常: %+v", confirmed)
257		}
258		rs := map[string]ItemResult{}
259		for _, r := range confirmed.Results {
260			if r.Limit != 100.0 || !r.LimitEffective.Equal(at(1, 0)) {
261				t.Fatalf("逐项限值异常: %+v", r)
262			}
263			rs[r.Item] = r
264		}
265		for _, item := range items {
266			if _, ok := rs[item]; !ok {
267				t.Fatalf("项目 %q 在确认结果中缺失: %+v", item, confirmed.Results)
268			}
269		}
270	
271		// 按点查看与返回记录一致
272		list, err := s.ListByPoint("P1")
273		if err != nil || len(list) != 1 {
274			t.Fatalf("按点查看异常: %+v err=%v", list, err)
275		}
276		listed := list[0]
277		if listed.ID != smp.ID {
278			t.Fatalf("按点查看记录不一致: %+v", listed)
279		}
280		if listed.PointID != "P1" || len(listed.Measurements) != len(items) {
281			t.Fatalf("按点查看记录不一致: %+v", listed)
282		}
283		listItems := map[string]bool{}
284		for _, m := range listed.Measurements {
285			listItems[m.Item] = true
286		}
287		for _, item := range items {
288			if !listItems[item] {
289				t.Fatalf("项目 %q 在按点查看中缺失", item)
290			}
291		}
292	
293		// 重开后保存的数据与录入时一致
294		if err := s.Close(); err != nil {
295			t.Fatalf("Close: %v", err)
296		}
297		s2, err := Open(dir)
298		if err != nil {
299			t.Fatalf("reopen: %v", err)
300		}
301		defer s2.Close()
302		reopened, err := s2.ListByPoint("P1")
303		if err != nil || len(reopened) != 1 {
304			t.Fatalf("重开后按点查看异常: %+v err=%v", reopened, err)
305		}
306		fromDisk := reopened[0]
307		if fromDisk.ID != "S-�-01" {
308			t.Fatalf("重开后记录与录入不一致: %+v", fromDisk)
309		}
310		if fromDisk.PointID != "P1" || fromDisk.Status != StatusConfirmed || len(fromDisk.Measurements) != len(items) {
311			t.Fatalf("重开后记录与录入不一致: %+v", fromDisk)
312		}
313		diskItems := map[string]bool{}
314		for _, m := range fromDisk.Measurements {
315			diskItems[m.Item] = true
316		}
317		for _, item := range items {
318			if !diskItems[item] {
319				t.Fatalf("项目 %q 在保存数据中缺失或被改写", item)
320			}
321		}
322		// 全部测量值均不超过上限 100，重开后整份结论应原样保存为达标
323		if fromDisk.Exceeded || len(fromDisk.Results) != len(items) {
324			t.Fatalf("整份结论或逐项依据在保存数据中不一致: %+v", fromDisk)
325		}
326	}
